package com.loja.checkout.entrega;

import com.loja.checkout.dominio.Identificado;
import com.loja.checkout.dominio.Pedido;

import java.math.BigDecimal;

/**
 * Uma forma de o cliente receber o pedido: quanto custa, em quantos dias chega
 * e quais pedidos ela atende.
 */
public interface ModalidadeEntrega extends Identificado {

    BigDecimal frete(Pedido pedido);

    int prazoDias();

    default boolean atende(Pedido pedido) {
        return true;
    }
}
EOF
cat > entrega/Economica.java <<'EOF'
package com.loja.checkout.entrega;

import com.loja.checkout.dominio.Dinheiro;
import com.loja.checkout.dominio.Pedido;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;

@Component
public class Economica implements ModalidadeEntrega {

    private static final BigDecimal PARCELA_FIXA = new BigDecimal("12.00");
    private static final BigDecimal POR_KG = new BigDecimal("2.00");

    @Override
    public String codigo() {
        return "ECONOMICA";
    }

    @Override
    public BigDecimal frete(Pedido pedido) {
        return Dinheiro.arredondar(PARCELA_FIXA.add(POR_KG.multiply(pedido.pesoTotalKg())));
    }

    @Override
    public int prazoDias() {
        return 7;
    }
}
EOF
